def solve(df: pl.DataFrame) -> pl.DataFrame:
    unique_users = df["user"].unique()
    unique_actions = df["action"].unique()
    result = df.group_by("user").agg(pl.col("action").count().alias("count"))
    result = result.join(
        pl.DataFrame({"user": unique_users, "count": [0] * len(unique_users)}),
        on="user",
        how="left"
    )
    result = result.join(
        pl.DataFrame({
            "user": unique_users,
            "count": {action: 0 for action in unique_actions}
        }),
        on="user",
        how="left"
    )
    result = result.with_columns(
        pl.struct(["count"]).map_elements(lambda x: x.to_dict()).alias("counts")
    )
    result = result.with_columns(
        pl.struct(["count"]).map_elements(lambda x: x.to_dict()).alias("counts")
    )
    return result

